    "publishedAt": "28/10/2026 às 18:57",
    "category": "Congresso",
    "ingestedAt": "29/10/2026 às 09:12",
    "imageUrl": "https://www.camara.leg.br/midias/image/2026/10/img20261028163528536-768x473.jpg",
    "imageCaption": "Deputados na sessão do Plenário desta quarta-feira",
